drop_client_errors.nginx.conf:
daemon off;
worker_processes 1;
pid @ROOT@/nginx.pid;
error_log @ROOT@/error.log;
events { worker_connections 64; }
http {
 access_log off;
 client_body_temp_path @ROOT@/client_body;
 proxy_temp_path @ROOT@/proxy_temp;
 fastcgi_temp_path @ROOT@/fastcgi_temp;
 uwsgi_temp_path @ROOT@/uwsgi_temp;
 scgi_temp_path @ROOT@/scgi_temp;
 map $status $should_log { ~^5 1; default 0; }
log_format failures escape=json '{"id":"$http_x_request_id","uri":"$uri","status":$status}';
server { listen 127.0.0.1:@PORT@; access_log @ROOT@/failures.log failures if=$should_log;
 location = /okay { return 200 "ok"; }
 location = /redirect { return 302 /okay; }
 location = /switch { return 101; }
 location = /failed { return 503; }
 location / { return 404; }
}
}

