import collections,json,re,sys

def unique(pairs):
    out={}
    for key,value in pairs:
        if key in out:raise ValueError('duplicate JSON key')
        out[key]=value
    return out

def record(value):
    if not isinstance(value,dict) or set(value)!={'id','uri','status'}:raise ValueError('record schema')
    if not isinstance(value['id'],str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,80}',value['id']):raise ValueError('request id')
    if not isinstance(value['uri'],str) or not value['uri'].startswith('/'):raise ValueError('normalized URI')
    if type(value['status']) is not int or not 100<=value['status']<=599:raise ValueError('status')
    return value

def parse(text):
    try:return json.loads(text,object_pairs_hook=unique)
    except RecursionError as error:raise ValueError('excessive JSON nesting') from error

def audit(receipts,raw_log):
    if not isinstance(receipts,list) or not isinstance(raw_log,str):raise ValueError('input types')
    expected={}
    for row in receipts:
        record(row)
        if row['id'] in expected:raise ValueError('duplicate receipt id')
        expected[row['id']]=row
    observed=[]
    for line in raw_log.split('\n'):
        if line.strip():observed.append(record(parse(line)))
    counts=collections.Counter(row['id'] for row in observed)
    good={row['id'] for row in observed if expected.get(row['id'])==row}
    missing=sorted(key for key,row in expected.items() if row['status']>=400 and key not in good)
    unexpected=sorted({row['id'] for row in observed if row['id'] not in expected or expected[row['id']]['status']<400})
    duplicate=[]
    mismatched=sorted({row['id'] for row in observed if row['id'] in expected and row!=expected[row['id']]})
    return {'request_count':len(receipts),'expected_error_count':sum(row['status']>=400 for row in receipts),'logged_count':len(observed),
            'missing_ids':missing,'unexpected_ids':unexpected,'duplicate_ids':duplicate,'mismatched_ids':mismatched,
            'passed':not any((missing,unexpected,duplicate,mismatched))}

def main():
    if len(sys.argv)!=3:raise ValueError('usage: audit.py receipts.json failures.log')
    with open(sys.argv[1],encoding='utf8') as f:receipts=parse(f.read())
    with open(sys.argv[2],encoding='utf8') as f:log=f.read()
    print(json.dumps(audit(receipts,log),ensure_ascii=False,allow_nan=False))

if __name__=='__main__':
    try:main()
    except (ValueError,TypeError,OSError) as error:
        print(str(error),file=sys.stderr);sys.exit(2)

